"""Dimension vocabularies for voice metric attributes.

Everything in this module is declarative — no runtime state. The dimension
enums are the attribute-value vocabularies Rasa itself defines; provider
names, decision reasons, and error types are stamped as-is because they are
short developer-controlled tokens (engine ``name()`` values, detector reason
constants, exception class names), never user content.

The instruments these dimensions describe are declared in
:mod:`rasa.tracing.voice.metrics.instruments`.
"""

from __future__ import annotations

from enum import Enum


class VoiceComponent(str, Enum):
    """Voice pipeline stage a measurement belongs to."""

    ASR = "asr"
    TTS = "tts"
    PLAYBACK = "playback"
    COMPOSER = "composer"
    CHANNEL = "channel"


class VoiceOperation(str, Enum):
    """Named operation measured or failing within a component."""

    CONNECT = "connect"
    DISCONNECT = "disconnect"
    TRANSCRIBE = "transcribe"
    SYNTHESIZE = "synthesize"
    PLAY = "play"
    PROCESS_CHANNEL_MESSAGE = "process_channel_message"
    COMPOSE_EVENT = "compose_event"


class CallOutcome(str, Enum):
    """Terminal state of a voice call."""

    COMPLETED = "completed"
    DISCONNECTED = "disconnected"
    FAILED = "failed"


class InteractionOutcome(str, Enum):
    """Terminal decision or state of an interaction or measured operation.

    Also tags outcome-dependent duration measurements (playback, TTS synthesis).
    These are behavioral outcomes, not failures: an ignored barge-in or an
    interrupted playback is expected behavior recorded as an outcome, never
    counted as an operation failure.
    """

    ACCEPTED = "accepted"
    IGNORED = "ignored"
    TIMEOUT = "timeout"
    COMPLETED = "completed"
    INTERRUPTED = "interrupted"
    CANCELLED = "cancelled"
    ERROR = "error"


class AudioDirection(str, Enum):
    """Direction of audio relative to the agent."""

    INPUT = "input"
    OUTPUT = "output"
